_sage_const_1 = Integer(1); _sage_const_0 = Integer(0); _sage_const_2 = Integer(2); _sage_const_64 = Integer(64); _sage_const_4 = Integer(4); _sage_const_51 = Integer(51); _sage_const_17669 = Integer(17669)
from sage.all import *
